const S=()=>"smoothstep",a=(p,$,n,h)=>`M ${p} ${$} L ${n} ${h}`,s=(p,$,n,h,M=0)=>{const t=(p+n)/2,c=$+M,x=h+M;return`M ${p} ${c} L ${t} ${c} L ${t} ${x} L ${n} ${x}`},b=(p,$,n,h,M=0)=>{const t=n-p,c=Math.min(Math.abs(t)*.3,100),x=p+c,l=$+M,d=n-c,y=h+M;return`M ${p} ${$} C ${x} ${l}, ${d} ${y}, ${n} ${h}`},E=(p,$,n,h,M=0)=>{const t=n-p,c=h-$;let x=Math.min(Math.abs(t)*.5,150),l,d,y,m;if(t>0)l=p+x,d=$+M,y=n-x,m=h+M;else if(t<=0&&c!==0){const i=Math.min(Math.abs(t)*.6,200);c>0?(l=p+i,d=$+i*.3,y=n-i,m=h+i*.3):(l=p+i,d=$-i*.3,y=n-i,m=h-i*.3)}else l=p+80,d=$+(c>0?40:-40),y=n-80,m=h+(c>0?-40:40);return`M ${p} ${$} C ${l} ${d}, ${y} ${m}, ${n} ${h}`},P=(p,$,n,h,M=0)=>{const t=n-p,c=h-$,x=Math.min(Math.max(Math.abs(t)*.5,50),200);let l,d,y,m;if(t>=0)l=p+x,d=$+M,y=n-x,m=h+M;else{const i=Math.min(Math.abs(t)*.7,250);c>0?(l=p+i,d=$+i*.4,y=n-i,m=h+i*.4):c<0?(l=p+i,d=$-i*.4,y=n-i,m=h-i*.4):(l=p+i,d=$,y=n-i,m=h)}return`M ${p} ${$} C ${l} ${d}, ${y} ${m}, ${n} ${h}`},z=(p,$,n,h,M,t=0)=>{switch(p){case"straight":return a($,n,h,M);case"step":return s($,n,h,M,t);case"bezier":return b($,n,h,M,t);case"smoothbezier":return E($,n,h,M,t);case"smoothstep":default:return P($,n,h,M,t)}};export{S as a,z as g};
